import{_ as r,C as i,c as n,o as s,j as t,G as l,ag as d,a}from"./chunks/framework.DZ_cNctr.js";const h="/docs/screenshots/tiff-image.webp",w=JSON.parse('{"title":"TIFF Viewer","description":"Free online TIFF viewer: open .tif files from Fiji, ImageJ, cameras and other tools in your browser, with every channel, Z-stack and time point. From your disk or a link. Nothing to install.","frontmatter":{"title":"TIFF Viewer","description":"Free online TIFF viewer: open .tif files from Fiji, ImageJ, cameras and other tools in your browser, with every channel, Z-stack and time point. From your disk or a link. Nothing to install."},"headers":[],"relativePath":"guides/tiff.md","filePath":"guides/tiff.md"}'),c={name:"guides/tiff.md"};function f(p,e,m,g,u,F){const o=i("OpenViewer");return s(),n("div",null,[e[0]||(e[0]=t("h1",{id:"tiff-viewer",tabindex:"-1"},[a("TIFF Viewer "),t("a",{class:"header-anchor",href:"#tiff-viewer","aria-label":'Permalink to "TIFF Viewer"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("Open "),t("code",null,".tif"),a(" and "),t("code",null,".tiff"),a(" files in your browser: Fiji and ImageJ hyperstacks, images from cameras, and files saved with tifffile or napari. You get every channel, Z-stack and time point as it was saved. Channels keep their Fiji colour when the lookup table is one colour. TIFFs shared on Zenodo open by their link.")],-1)),l(o,{format:"TIFF",example:"https://find-nuclei.github.io/examples/formats/DataG-Fig1K_confocal.tif",view3d:"z=12&c=0%3Aon%3AFFFFFF%3A0%3A103%3A1.00&zm=0.38&xy=424%2C424&cm=C&inv=f&bg=%23000000&pj=none%3A0%3A23&l=&l3s=&mode=3d&layout=main&main=v3d&rm=composite&cam=86.58%2C67.36%2C-11.01%2C2.385%2C-0.1994%2C0.5382%2C-0.8189%2C-0.2921%2C0.7651%2C0.5739&den=1.38&bri=1.514&ramp=0%3A14%3A168",label:"a 407-million-year-old fossil fungus"}),e[2]||(e[2]=d('<p><img src="'+h+'" alt="PM-R_ER-G.tif open in the viewer: a Fiji hyperstack of plant cells, with each channel coloured as its Fiji lookup table"></p><h2 id="how-to-open-a-tiff-file" tabindex="-1">How to Open a TIFF File <a class="header-anchor" href="#how-to-open-a-tiff-file" aria-label="Permalink to &quot;How to Open a TIFF File&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Working with many files?</p><p>Several files chosen together, or a zip of them, open as a <a href="./many-images.html">gallery</a> in every browser. A whole folder opens in Chrome and Edge on a computer, not in Firefox and Safari.</p></div><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on <a href="https://find-nuclei.github.io/" target="_blank" rel="noreferrer">the viewer</a>, or click <strong>Open Image</strong> and <strong>Choose Files</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of TIFF files</strong>, in Chrome and Edge. One file opens. Several show a list by name, with a picture of each, and files one folder down are listed too. After you pick one, a gallery of pictures under the image takes you to the next. See <a href="./many-images.html">Folders, Zips and Series</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>, or a Zenodo file link that ends in <code>/content</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>Fiji and ImageJ hyperstacks</strong> with their channels, Z planes and time points, as Fiji saved them.</li><li><strong>Channel colours</strong> from each channel&#39;s lookup table. A Green LUT shows green, and Grays shows white. A file with no lookup tables gets Fiji&#39;s composite order: red, green, blue, white, cyan, magenta, yellow. One channel alone is white.</li><li><strong>Other lookup tables</strong>, such as Fire or Glasbey, in white, with a note. Pick a colour on the channel&#39;s swatch. See <a href="./channels.html#channel-colors">Channel colors</a>.</li><li><strong>Pixel size, Z step and time interval</strong> from a Fiji file. A plain TIFF gives its pixel size when it is stated in centimetres and fits a microscope image. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li><li><strong>Plain multi-page TIFFs</strong> as a Z-stack. Sliders step through the planes, and a Z-stack can also be viewed in 3D. See <a href="./3d-rendering.html">3D Rendering</a>. A time series saved as plain pages steps through on the Z slider.</li><li><strong>Colour images</strong> from a camera as a colour photograph. A transparency (alpha) layer is left out.</li><li><strong>8, 16 and 32-bit data</strong>, whole numbers or 32-bit float. Uncompressed, LZW, Deflate, PackBits, JPEG or JPEG 2000. Classic TIFF and BigTIFF, and Fiji files over 4 GB.</li><li><strong>Pyramidal TIFFs</strong> with the resolutions stored in the file. A TIFF with one resolution gets lower ones made by the viewer, so a large image zooms out and opens in 3D.</li><li><strong>An OME-TIFF without <code>.ome</code> in its name</strong> opens as an OME-TIFF. See <a href="./ome-tiff.html">OME-TIFF</a>. <strong>An Aperio slide saved as <code>.tif</code></strong> opens as a slide. See <a href="./aperio-svs.html">Aperio SVS</a>.</li></ul><p>Contrast starts from auto contrast on each channel. Fiji&#39;s saved display range, ROIs and overlays are not read yet.</p><h2 id="if-a-file-does-not-open" tabindex="-1">If a File Does Not Open <a class="header-anchor" href="#if-a-file-does-not-open" aria-label="Permalink to &quot;If a File Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th><th>What to do</th></tr></thead><tbody><tr><td>Bytes that are not a TIFF</td><td>This file is not a TIFF.</td><td>Check that it is the image file itself. See <a href="./supported-formats.html">Supported Formats</a> for other kinds.</td></tr><tr><td>A file that is cut short or damaged</td><td>This TIFF looks damaged or incomplete.</td><td>Download or copy it again. If it still fails, open it in Fiji and save it again.</td></tr><tr><td>Another compression, such as Zstd</td><td>This TIFF uses a compression the viewer cannot read yet (TIFF code 50000).</td><td>Save it again from Fiji with <strong>File &gt; Save As &gt; Tiff</strong>.</td></tr><tr><td>Another pixel type, such as 1, 12 or 24-bit, or 64-bit float</td><td>This TIFF has a pixel type the viewer cannot read yet (64-bit float).</td><td>In Fiji, choose <strong>Image &gt; Type &gt; 16-bit</strong> or <strong>32-bit</strong>, then save.</td></tr><tr><td>Colours stored as CMYK, Lab or another colour model</td><td>This TIFF stores its colours as CMYK, which the viewer cannot show yet.</td><td>Save it again as RGB in the program that made it.</td></tr><tr><td>An ImageJ file with several samples in each pixel, such as a colour stack with channels</td><td>This ImageJ TIFF has a layout the viewer cannot read yet.</td><td>In Fiji, choose <strong>Image &gt; Color &gt; Make Composite</strong>, then save.</td></tr><tr><td>One plane of all channels over 256 MB, with no pyramid</td><td>This TIFF is too large to open without a pyramid. Convert it to OME-Zarr to open it here.</td><td><a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">Convert to OME-Zarr</a> to open it with every resolution.</td></tr></tbody></table><p>A file can also open with a note:</p><table tabindex="0"><thead><tr><th>What the viewer says</th><th>What it means</th></tr></thead><tbody><tr><td>Channel 1 uses a Fiji lookup table the viewer cannot show yet. It is shown in white.</td><td>The channel&#39;s lookup table is not one colour. Pick a colour on its swatch.</td></tr><tr><td>No pixel size in this file.</td><td>The file states no pixel size a microscope could have. <a href="./calibration.html">Set your own</a>.</td></tr><tr><td>Other images in this file are not shown.</td><td>The file holds images of another size or kind. The first image and its stack open.</td></tr><tr><td>This image is stored with white as zero. It is shown as stored.</td><td>The file marks zero as white. The viewer shows the stored values, so bright and dark can look swapped.</td></tr></tbody></table><h2 id="public-tiff-files-to-try" tabindex="-1">Public TIFF Files to Try <a class="header-anchor" href="#public-tiff-files-to-try" aria-label="Permalink to &quot;Public TIFF Files to Try&quot;">​</a></h2><ul><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F16966021%2Ffiles%2FArabidopsis%2520pollen%2520tube2.tif%2Fcontent" target="_blank" rel="noreferrer">Arabidopsis pollen tube2.tif</a>: a Fiji hyperstack, three channels, 12 Z planes and 50 time points, 21.5 MB. <a href="https://zenodo.org/records/16966021" target="_blank" rel="noreferrer">Zenodo 16966021</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F16966021%2Ffiles%2FPM-R_ER-G.tif%2Fcontent" target="_blank" rel="noreferrer">PM-R_ER-G.tif</a>: a Fiji hyperstack, four channels and 16 Z planes, 134 MB. <a href="https://zenodo.org/records/16966021" target="_blank" rel="noreferrer">Zenodo 16966021</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F12600359%2Ffiles%2FtrpL_150310-11.tif%2Fcontent" target="_blank" rel="noreferrer">trpL_150310-11.tif</a>: a time-lapse of bacteria from Fiji, two channels and 20 time points, 60 MB. <a href="https://zenodo.org/records/12600359" target="_blank" rel="noreferrer">Zenodo 12600359</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F15194428%2Ffiles%2FDataG-Fig1K_confocal.tif%2Fcontent" target="_blank" rel="noreferrer">DataG-Fig1K_confocal.tif</a>: a confocal Z-stack from Fiji, 24 planes, 17 MB. <a href="https://zenodo.org/records/15194428" target="_blank" rel="noreferrer">Zenodo 15194428</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F4017365%2Ffiles%2Foutput_period_rotated_001-120_LUVELU_MAX_20170605_W0010-1.tif%2Fcontent" target="_blank" rel="noreferrer">output_period_rotated_001-120_LUVELU_MAX_20170605_W0010-1.tif</a>: a movie of 120 frames in 32-bit float, written by tifffile, 126 MB. It is a plain stack, so the frames step through on the Z slider. <a href="https://zenodo.org/records/4017365" target="_blank" rel="noreferrer">Zenodo 4017365</a>, CC BY 4.0.</li></ul><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a file by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>PM-R_ER-G.tif</code>, Ivan Radin and Kirk Czymmek, <a href="https://zenodo.org/records/16966021" target="_blank" rel="noreferrer">Zenodo 16966021</a>, CC BY 4.0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><ul><li><code>Arabidopsis pollen tube2.tif</code> and <code>PM-R_ER-G.tif</code>: Ivan Radin and Kirk Czymmek, <em>PCA Imaging Workshop Webinar Series: FIJI Basics for Visualizing and Quantifying Plant Images!</em>, <a href="https://zenodo.org/records/16966021" target="_blank" rel="noreferrer">Zenodo 16966021</a>, CC BY 4.0.</li><li><code>trpL_150310-11.tif</code>: Simon van Vliet and Annina Winkler, <em>Trackastra integration in TrackMate example</em>, <a href="https://zenodo.org/records/12600359" target="_blank" rel="noreferrer">Zenodo 12600359</a>, CC BY 4.0.</li><li><code>DataG-Fig1K_confocal.tif</code>: Christine Strullu-Derrien et al., <em>Supplemental Confocal Laser Scanning Microscopy Data - An arbuscular mycorrhiza from the 407-million-year-old Windyfield chert identified through advanced fluorescence and Raman imaging (tif format)</em>, <a href="https://zenodo.org/records/15194428" target="_blank" rel="noreferrer">Zenodo 15194428</a>, CC BY 4.0.</li><li><code>output_period_rotated_001-120_LUVELU_MAX_20170605_W0010-1.tif</code>: Paul Gerald Layague Sanchez, <em>Period wavelet movies of spreadouts, ex vivo models of somitogenesis, subjected to 170-min periodic pulses of 2 uM DAPT</em>, <a href="https://zenodo.org/records/4017365" target="_blank" rel="noreferrer">Zenodo 4017365</a>, CC BY 4.0.</li></ul><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The file is read in your browser. Opening one counts as one opened image of the kind &quot;TIFF file&quot;, or &quot;ImageJ TIFF file&quot; for a file from Fiji or ImageJ. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p>',21))])}const y=r(c,[["render",f]]);export{w as __pageData,y as default};
